async (page) => {
  const fs = require('fs');
  const path = require('path');

  // Get current time
  const now = new Date();
  const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

  // Recursively get all files
  function getAllFiles(dir, fileList = []) {
    const files = fs.readdirSync(dir);

    files.forEach(file => {
      const filePath = path.join(dir, file);
      const stat = fs.statSync(filePath);

      if (stat.isFile()) {
        fileList.push(filePath);
      } else if (stat.isDirectory()) {
        getAllFiles(filePath, fileList);
      }
    });

    return fileList;
  }

  const workspaceDir = '/tmp/mcp-workspace/workspace';
  const allFiles = getAllFiles(workspaceDir);

  // Filter files modified in last 24 hours
  const recentFiles = allFiles.filter(file => {
    const stat = fs.statSync(file);
    return stat.mtime > oneDayAgo;
  });

  return {
    total_files: allFiles.length,
    recent_files: recentFiles.sort(),
    cutoff_time: oneDayAgo.toISOString(),
    current_time: now.toISOString()
  };
}

